#!/usr/bin/env python3
import sys
from Bio import SeqIO

def extract_gene(header):
    """Extract gene name from header like [gene=TP53]"""
    if '[gene=' in header:
        start = header.find('[gene=') + 7
        end = header.find(']', start)
        if end > start:
            return header[start:end]
    return None

def calculate_gc(sequence):
    """Calculate GC percentage (case-insensitive)"""
    if not sequence:
        return 0.0
    seq_upper = str(sequence).upper()
    gc_count = seq_upper.count('G') + seq_upper.count('C')
    total_length = len(seq_upper)
    if total_length == 0:
        return 0.0
    return round((gc_count / total_length) * 100, 2)

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    fasta_path = sys.argv[1]

    for record in SeqIO.parse(fasta_path, "fasta"):
        gene = extract_gene(record.description)
        if gene:
            gc = calculate_gc(record.seq)
            print(f"{gene}\t{gc}")

if __name__ == "__main__":
    main()
