#!/usr/bin/env python3
import sys

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    gff_file = sys.argv[1]

    feature_counts = {}
    total_cds_bp = 0

    with open(gff_file, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue

            fields = line.split('\t')
            if len(fields) < 3:
                continue

            feature_type = fields[2]
            feature_counts[feature_type] = feature_counts.get(feature_type, 0) + 1

            if feature_type == 'CDS':
                start = int(fields[3])
                end = int(fields[4])
                total_cds_bp += (end - start + 1)

    for feature_type in sorted(feature_counts.keys()):
        print(f"{feature_type}\t{feature_counts[feature_type]}")

    print(f"total_cds_bp\t{total_cds_bp}")

if __name__ == "__main__":
    main()
